  l_failures              PLS_INTEGER := 0;

  l_match_id              NUMBER;
  l_no_match_id           NUMBER := -1;
  l_null_id               NUMBER := NULL;

  l_candidate_count       NUMBER;
  l_expected_match        NUMBER;
  l_expected_no_match     NUMBER;
  l_expected_null         NUMBER;
  l_actual                NUMBER;

  PROCEDURE check_result(
    p_check_name   IN VARCHAR2,
    p_expected     IN NUMBER,
    p_actual       IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
      l_failures := l_failures + 1;
    END IF;
  END check_result;
BEGIN
  SAVEPOINT test_headcount_sp;

  -- Check 1: a department_id that has at least one employee row.
  SELECT MIN(department_id)
    INTO l_match_id
    FROM harness_app.employees
   WHERE department_id IS NOT NULL;

  IF l_match_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: matching department_id check setup found no non-NULL department_id in harness_app.employees'
    );
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_match
      FROM harness_app.employees
     WHERE department_id = l_match_id;

    l_actual := harness_app.headcount(l_match_id);

    check_result(
      p_check_name => 'matching department_id',
      p_expected   => l_expected_match,
      p_actual     => l_actual
    );
  END IF;

  -- Check 2: a non-NULL department_id that matches no employee row.
  SELECT COUNT(*)
    INTO l_candidate_count
    FROM harness_app.employees
   WHERE department_id = l_no_match_id;

  IF l_candidate_count <> 0 THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: non-matching department_id check setup could not confirm that -1 matches no row in harness_app.employees'
    );
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_no_match
      FROM harness_app.employees
     WHERE department_id = l_no_match_id;

    l_actual := harness_app.headcount(l_no_match_id);

    check_result(
      p_check_name => 'non-matching department_id',
      p_expected   => l_expected_no_match,
      p_actual     => l_actual
    );
  END IF;

  -- Check 3: NULL argument.
  -- The function compares with department_id = p_department_id.
  -- For a NULL argument, that comparison matches no row, so the expected
  -- result is the no-match result, not a count of rows where department_id IS NULL.
  SELECT COUNT(*)
    INTO l_expected_null
    FROM harness_app.employees
   WHERE department_id = l_null_id;

  l_actual := harness_app.headcount(l_null_id);

  check_result(
    p_check_name => 'NULL argument',
    p_expected   => l_expected_null,
    p_actual     => l_actual
  );

  ROLLBACK TO test_headcount_sp;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed: ' || l_failures || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_headcount_sp;
    RAISE;
END;
```

The block calls the stored function by name, `harness_app.headcount`, rather than copying its code into the test. It checks three cases:

1. A `department_id` that exists in `harness_app.employees`. The expected count is computed independently with a separate `COUNT(*)` query using the same equality predicate as the function. If no non-NULL `department_id` can be found, the check prints `FAIL` and counts as a failure.

2. A non-NULL `department_id` that matches no employee row. The block uses `-1` as the candidate and confirms with `COUNT(*)` that it matches no row. If that confirmation fails, the check prints `FAIL` and counts as a failure.

3. A `NULL` argument. Because the function compares with `department_id = p_department_id`, a `NULL` argument matches no row, including rows where `department_id IS NULL`. The expected value is therefore the no-match result, computed with the same equality predicate.

The block starts with a savepoint and ends by rolling back to it, so it does not commit. If an unexpected exception occurs, it reports the error, rolls back to the savepoint, and re-raises. I have not run this block.

